import time
import random

def compute_n(B):
    B = sorted(set(B))
    if len(B) < 2:
        return 0
    diffs = set()
    for i in range(len(B)):
        for j in range(i+1, len(B)):
            diffs.add(B[j] - B[i])
    n = 0
    while (n + 1) in diffs:
        n += 1
    return n

def score_of(B):
    B = sorted(set(B))
    if 0 not in B:
        return -10.0  # invalid if 0 missing
    n = compute_n(B)
    if n <= 0:
        return -1e9
    return - (len(B) ** 2) / float(n)

def ensure_contains_0(B):
    s = sorted(set(B))
    if 0 not in s:
        s = [0] + s
    return sorted(set(s))

