def neighborhood_moves(B, max_elem=200):
    Bset = set(B)
    moves = []
    # removals (except 0)
    for x in B:
        if x == 0:
            continue
        moves.append(("remove", x))
    # additions
    for y in range(0, max_elem+1):
        if y in Bset:
            continue
        moves.append(("add", y))
    # swaps
    for i, x in enumerate(B):
        if x == 0:
            continue
        for y in range(0, max_elem+1):
            if y in Bset:
                continue
            if y == x:
                continue
            moves.append(("swap", i, y))
    return moves

