def compute_n(B):
    # largest n such that 1..n are all differences of pairs in B
    s = set()
    B = sorted(set(B))
    L = len(B)
    for i in range(L):
        bi = B[i]
        for j in range(i+1, L):
            s.add(B[j] - bi)
    n = 0
    while (n + 1) in s:
        n += 1
    return n

def contrast_score(B, n=None):
    B = sorted(set(B))
    if 0 not in B:
        return -1e6
    if n is None:
        n = compute_n(B)
    if n <= 0:
        return -1e6  # invalid
    return - (len(B) ** 2) / float(n)

def ensure_valid(B):
    B = sorted(set(B))
    if 0 not in B:
        B = [0] + B
    if compute_n(B) <= 0:
        return None
    return B

